/// Whether one character is East Asian wide, full-width or half-width.
pub(crate) fn width_of(character: char) -> Width {
    let code = character as u32;
    let after = WIDTHS.partition_point(|(first, _)| *first <= code);
    WIDTHS[after - 1].1
}

