/// Whether a code point falls in one of a table's ranges.
pub(crate) fn within(table: &[(u32, u32)], code: u32) -> bool {
    let after = table.partition_point(|(first, _)| *first <= code);
    after > 0 && table[after - 1].1 >= code
}

/// Whether the tables are in order and leave no character out, which is
/// what the searches above take for granted.
#[cfg(test)]
pub(crate) fn in_order() -> bool {
    CLASSES[0].0 == 0
        && CLASSES.windows(2).all(|pair| pair[0].0 < pair[1].0)
        && WIDTHS[0].0 == 0
        && WIDTHS.windows(2).all(|pair| pair[0].0 < pair[1].0)
}
